// "Mac" and "Windows" styles: full sets drawn for this extension (inspired by, not copied from,
// the system cursors). Mac: rounded shapes, black arrow with a white outline. Windows: sharper
// shapes, white arrow with a black outline. Hands are white with a black outline in both.
//
// Hands are original vector drawings that keep the main traits of each system:
//   Mac:     thick rounded outline, fingers split by short notches, thumb to the left,
//            three small vertical lines on the back of the hand.
//   Windows: thin crisp outline, long lines between fingers, diagonal thumb.
// Finger lines start exactly at the dip between two fingers (a vertex of the outline), so they
// always meet the outline without a gap or a thicker spot.
// Units are pixels at 1×. `o` offsets the drawing to leave room for the outline stroke.

function ksHandSvg(d) {
  const lines = (arr) => arr.map(([x, y0, y1]) => `M${x} ${y0} L${x} ${y1}`).join(' ');
  // The path is written without margin: a translate shifts it by `o` to make room for the stroke.
  return (
    `<svg width="${d.w}" height="${d.h}" viewBox="0 0 ${d.w} ${d.h}" xmlns="http://www.w3.org/2000/svg"><g transform="translate(${d.o} ${d.o})">` +
    `<path d="${d.path}" fill="#fff" stroke="#000" stroke-width="${d.stroke}" stroke-linejoin="${d.join}"/>` +
    (d.seams.length
      ? `<path d="${lines(d.seams)}" stroke="#000" stroke-width="${d.seamW}" stroke-linecap="butt" fill="none"/>`
      : '') +
    (d.bars && d.bars.length
      ? `<path d="${lines(d.bars)}" stroke="#000" stroke-width="${d.barW}" stroke-linecap="round" fill="none"/>`
      : '') +
    `</g></svg>`
  );
}

function ksArc(r, x, y) {
  return `A${r} ${r} 0 0 1 ${x} ${y}`;
}

